#include "astc_gles.h"
#include "shader_source.h" // generated by CMake: gpuastc::kShaderSource

#include <cstdlib>
#include <vector>

namespace gpuastc {

// ---------------------------------------------------------------------------
// Two-partition patterns of a 4x4 block. The format derives each pattern from a 10 bit seed with
// a hash (ASTC specification, "Partition Pattern Generation"); the shader needs the reverse: for
// a wanted split of the 16 texels, the seed whose pattern is closest.
// ---------------------------------------------------------------------------

static uint32_t hash52(uint32_t p)
{
    p ^= p >> 15; p -= p << 17; p += p << 7; p += p << 4;
    p ^= p >> 5;  p += p << 16; p ^= p >> 7; p ^= p >> 3;
    p ^= p << 6;  p ^= p >> 17;
    return p;
}

// Group (0 or 1) of texel (x, y) of a 4x4 block for a two-partition seed.
static int select_partition2(int seed, int x, int y)
{
    x <<= 1; y <<= 1; // blocks under 31 texels
    seed += 1024;     // (partition count - 1) * 1024
    const uint32_t r = hash52((uint32_t)seed);
    int s1 = r & 0xF, s2 = (r >> 4) & 0xF, s3 = (r >> 8) & 0xF, s4 = (r >> 12) & 0xF;
    s1 *= s1; s2 *= s2; s3 *= s3; s4 *= s4;
    const int sh1 = (seed & 1) ? ((seed & 2) ? 4 : 5) : 5;
    const int sh2 = (seed & 1) ? 5 : ((seed & 2) ? 4 : 5);
    s1 >>= sh1; s2 >>= sh2; s3 >>= sh1; s4 >>= sh2;
    const int a = (s1 * x + s2 * y + (int)(r >> 14)) & 0x3F;
    const int b = (s3 * x + s4 * y + (int)(r >> 10)) & 0x3F;
    return a >= b ? 0 : 1;
}

// 65536 entries: seed | texels that differ << 10 | the pattern's own mask << 16.
// Bit i of a mask is the group of texel i (x + 4 * y).
static std::vector<uint32_t> build_partition_table()
{
    std::vector<uint32_t> val(65536, 0);
    std::vector<uint8_t> dist(65536, 255);
    std::vector<uint32_t> frontier, next;
    for (int seed = 1023; seed >= 0; --seed) { // lowest seed wins
        uint32_t mask = 0;
        for (int i = 0; i < 16; ++i)
            mask |= (uint32_t)select_partition2(seed, i & 3, i >> 2) << i;
        if (mask == 0 || mask == 0xFFFF)
            continue; // everything in one group
        for (uint32_t m : {mask, mask ^ 0xFFFFu}) {
            if (dist[m] != 0) frontier.push_back(m);
            dist[m] = 0;
            val[m] = (uint32_t)seed | (mask << 16);
        }
    }
    // breadth-first over single texel flips: every mask gets its nearest pattern
    for (uint8_t d = 1; !frontier.empty(); ++d) {
        next.clear();
        for (uint32_t m : frontier)
            for (int b = 0; b < 16; ++b) {
                const uint32_t n = m ^ (1u << b);
                if (dist[n] == 255) {
                    dist[n] = d;
                    val[n] = val[m];
                    next.push_back(n);
                }
            }
        frontier.swap(next);
    }
    for (int m = 0; m < 65536; ++m)
        val[m] |= (uint32_t)dist[m] << 10;
    return val;
}

static GLuint g_partition_tex = 0; // one per GL context, shared by every Encoder

static GLuint partition_texture()
{
    if (!g_partition_tex) {
        const std::vector<uint32_t> table = build_partition_table();
        glGenTextures(1, &g_partition_tex);
        glBindTexture(GL_TEXTURE_2D, g_partition_tex);
        glTexStorage2D(GL_TEXTURE_2D, 1, GL_R32UI, 256, 256);
        glTexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, 256, 256, GL_RED_INTEGER, GL_UNSIGNED_INT, table.data());
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
    }
    return g_partition_tex;
}

GLenum Encoder::internal_format(int block)
{
    switch (block) {
    case 6:  return 0x93B4u; // GL_COMPRESSED_RGBA_ASTC_6x6_KHR
    case 5:  return 0x93B2u; // GL_COMPRESSED_RGBA_ASTC_5x5_KHR
    default: return 0x93B0u; // GL_COMPRESSED_RGBA_ASTC_4x4_KHR
    }
}

int Encoder::pick_block(int width, int height, bool alpha)
{
    const long long area = (long long)width * height;
    const int shortest = width < height ? width : height;
    if (alpha || shortest <= 64 || area <= 256LL * 256)
        return 4;
    if (area <= 2048LL * 2048)
        return 5;
    return 6;
}

Encoder::~Encoder() { destroy(); }

void Encoder::destroy()
{
    if (program_) {
        glDeleteProgram(program_);
        program_ = 0;
    }
}

bool Encoder::create(const Options& opt, std::string* log)
{
    destroy();
    opt_ = opt;

    std::string src = "#version 310 es\n";
    src += "#define BLOCK_DIM " + std::to_string(opt.block) + "\n";
    src += std::string("#define HAS_ALPHA ") + (opt.alpha ? "1" : "0") + "\n";
    src += std::string("#define PREMULTIPLIED ") + (opt.alpha && opt.premultiplied ? "1" : "0") + "\n";
    src += std::string("#define IS_NORMALMAP ") + (opt.normal_map ? "1" : "0") + "\n";
    if (opt.quality <= 0)
        src += "#define USE_PARTITIONS 0\n";
    else if (opt.quality >= 2)
        src += "#define PART_CANDIDATES 3\n#define ALT_ERR_THRESHOLD 64.0\n";
    // Tuning hook: GPUASTC_SHADER_DEFINES="NAME=VALUE;NAME=VALUE" overrides shader defaults
    // (ALT_ERR_THRESHOLD, PART_CANDIDATES, USE_PARTITIONS, ...).
    if (const char* extra = std::getenv("GPUASTC_SHADER_DEFINES")) {
        std::string def;
        for (const char* c = extra;; ++c) {
            if (*c == ';' || *c == 0) {
                if (!def.empty()) src += "#define " + def + "\n";
                def.clear();
                if (*c == 0) break;
            } else {
                def += (*c == '=') ? ' ' : *c;
            }
        }
    }
    src += kShaderSource;

    GLuint sh = glCreateShader(GL_COMPUTE_SHADER);
    const char* p = src.c_str();
    glShaderSource(sh, 1, &p, nullptr);
    glCompileShader(sh);

    auto get_log = [&](bool is_prog, GLuint obj) {
        GLint len = 0;
        if (is_prog) glGetProgramiv(obj, GL_INFO_LOG_LENGTH, &len);
        else glGetShaderiv(obj, GL_INFO_LOG_LENGTH, &len);
        std::string s(len > 1 ? len : 1, '\0');
        if (is_prog) glGetProgramInfoLog(obj, len, nullptr, &s[0]);
        else glGetShaderInfoLog(obj, len, nullptr, &s[0]);
        return s;
    };

    GLint ok = 0;
    glGetShaderiv(sh, GL_COMPILE_STATUS, &ok);
    if (!ok) {
        if (log) *log = get_log(false, sh);
        glDeleteShader(sh);
        return false;
    }

    program_ = glCreateProgram();
    glAttachShader(program_, sh);
    glLinkProgram(program_);
    glDeleteShader(sh);

    glGetProgramiv(program_, GL_LINK_STATUS, &ok);
    if (!ok) {
        if (log) *log = get_log(true, program_);
        destroy();
        return false;
    }

    if (opt.block == 4 && opt.quality > 0)
        partition_texture(); // built here so the first encode does not pay for it
    loc_tex_size_ = glGetUniformLocation(program_, "uTexSize");
    loc_blocks_ = glGetUniformLocation(program_, "uBlocks");
    loc_count_ = glGetUniformLocation(program_, "uN");
    return true;
}

bool Encoder::encode(GLuint tex, int width, int height, GLuint out_buffer)
{
    if (!program_ || width <= 0 || height <= 0)
        return false;

    const int bx = blocks(width, opt_.block);
    const int by = blocks(height, opt_.block);

    glBindBuffer(GL_SHADER_STORAGE_BUFFER, out_buffer);
    glBufferData(GL_SHADER_STORAGE_BUFFER, (GLsizeiptr)bx * by * 16, nullptr, GL_DYNAMIC_COPY);
    glBindBufferBase(GL_SHADER_STORAGE_BUFFER, 0, out_buffer);

    if (opt_.block == 4 && opt_.quality > 0) { // partition patterns, texture unit 1
        const GLuint table = partition_texture();
        glActiveTexture(GL_TEXTURE1);
        glBindTexture(GL_TEXTURE_2D, table);
    }
    glActiveTexture(GL_TEXTURE0);
    glBindTexture(GL_TEXTURE_2D, tex);

    glUseProgram(program_);
    glUniform2i(loc_tex_size_, width, height);
    glUniform2i(loc_blocks_, bx, by);
    glUniform1i(loc_count_, opt_.block * opt_.block); // texels per block; keeps shader loops rolled
    glDispatchCompute((bx + 7) / 8, (by + 7) / 8, 1);

    glMemoryBarrier(GL_BUFFER_UPDATE_BARRIER_BIT | GL_PIXEL_BUFFER_BARRIER_BIT);
    return glGetError() == GL_NO_ERROR;
}

} // namespace gpuastc
